189	            this.pets = new HashSet<>();
190	        }
191	        return this.pets;
192	    }
193	
194	    protected void setPetsInternal(Set<Pet> pets) {
195	        this.pets = pets;
196	    }
197	
198	    public List<Pet> getPets() {
199	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
200	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
201	        return Collections.unmodifiableList(sortedPets);
202	    }
203	
204	    public void setPets(List<Pet> pets) {
205	        this.pets = new HashSet<>(pets);
206	    }
