212	
213	    /**
214	     * Return the Pet with the given name, or null if none found for this Owner.
215	     *
216	     * @param name to test
217	     * @return true if pet name is already in use
218	     */
219	    public Pet getPet(String name) {
220	        return getPet(name, false);
221	    }
222	
223	    /**
224	     * Return the Pet with the given name, or null if none found for this Owner.
225	     *
226	     * @param name to test
227	     * @return true if pet name is already in use
228	     */
229	    public Pet getPet(String name, boolean ignoreNew) {
230	        name = name.toLowerCase();
231	        for (Pet pet : getPetsInternal()) {
232	            if (!ignoreNew || !pet.isNew()) {
233	                String compName = pet.getName();
234	                compName = compName.toLowerCase();
235	                if (compName.equals(name)) {
236	                    return pet;
237	                }
238	            }
239	        }
240	        return null;
241	    }
242	
243	    public Pet getPet(Integer petId) {
244	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
245	    }
246	
247	    @Override
248	    public String toString() {
249	        return new ToStringCreator(this)
250	
251	            .append("id", this.getId())
252	            .append("new", this.isNew())
253	            .append("lastName", this.getLastName())
254	            .append("firstName", this.getFirstName())
255	            .append("address", this.address)
256	            .append("city", this.city)
257	            .append("telephone", this.telephone)
258	            .toString();
259	    }
260	}
