1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	import net.officefloor.plugin.variable.Val;
8	import org.springframework.samples.petclinic.model.Owner;
9	
10	/**
11	 * Assigns every owner a deterministic {@code householdId}: the first 12 hex characters of SHA-256
12	 * over {@code normalizedLastName + '|' + postcode}. Owners with the same last name and postcode are
13	 * therefore the same household and share this id automatically, with no opt-in or back-fill. Runs
14	 * before the household duplicate block so that block can compare on the computed id.
15	 */
16	public class AssignHousehold {
17	
18	    public void service(@Val Owner owner) {
19	        String key = normalize(owner.getLastName()) + "|" + orEmpty(owner.getPostcode());
20	        owner.setHouseholdId(hash12(key));
21	    }
22	
23	    /** First 12 lower-case hex characters of SHA-256 over the UTF-8 bytes of {@code key}. */
24	    private static String hash12(String key) {
25	        try {
26	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
27	            StringBuilder sb = new StringBuilder(12);
28	            for (int i = 0; i < 6; i++) {
29	                sb.append(String.format("%02x", digest[i]));
30	            }
31	            return sb.toString();
32	        }
33	        catch (NoSuchAlgorithmException ex) {
34	            throw new IllegalStateException(ex);
35	        }
36	    }
37	
38	    private static String normalize(String value) {
39	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase();
40	    }
41	
42	    private static String orEmpty(String value) {
43	        return value == null ? "" : value;
44	    }
45	}
