1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Map;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.rest.escalation.InvalidPostcodeException;
8	
9	/**
10	 * When an owner supplies a postcode, rejects it when it falls outside the inclusive range for the
11	 * city's region (Sydney/NSW 2000-2099, Melbourne/VIC 3000-3099, Brisbane/QLD 4000-4099). A city
12	 * with no known region accepts any 4-digit postcode, and an absent postcode is always accepted.
13	 * The 4-digit shape is already enforced by the request DTO, so a present postcode parses cleanly.
14	 */
15	public class ValidatePostcode {
16	
17	    private static final Map<String, int[]> REGION_RANGES = Map.of(
18	            "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
19	
20	    private static final Map<String, String> CITY_REGION = Map.of(
21	            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
22	
23	    public void service(@Val Owner owner) throws InvalidPostcodeException {
24	        String postcode = owner.getPostcode();
25	        if (postcode == null) {
26	            return;
27	        }
28	        String region = CITY_REGION.get(owner.getCity());
29	        if (region == null) {
30	            return;
31	        }
32	        int[] range = REGION_RANGES.get(region);
33	        int value = Integer.parseInt(postcode);
34	        if (value < range[0] || value > range[1]) {
35	            throw new InvalidPostcodeException(owner.getCity(), postcode);
36	        }
37	    }
38	}
