1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdException;
7	
8	/**
9	 * Rejects a new owner whose deterministic {@code householdId} (derived from last name and postcode by
10	 * {@link AssignHousehold}) already belongs to another owner. Skipped when the request opts in with
11	 * {@code sharesHousehold: true}, in which case the owner is created as a declared household member.
12	 * Runs after {@link AssignHousehold} and before Save, so the conflict is a 409, not a persisted
13	 * duplicate.
14	 */
15	public class EnsureUniqueHousehold {
16	
17	    public void service(@Val Owner owner, @Val Boolean sharesHousehold, OwnerRepository ownerRepository)
18	            throws DuplicateHouseholdException {
19	        if (Boolean.TRUE.equals(sharesHousehold)) {
20	            return;
21	        }
22	        String householdId = owner.getHouseholdId();
23	        for (Owner existing : ownerRepository.findAll()) {
24	            if (householdId.equals(existing.getHouseholdId())) {
25	                throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
26	            }
27	        }
28	    }
29	}
