1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Records a soft-match duplicate: an existing owner in the same household (same computed
9	 * {@code householdId}) but with a different telephone (so it is not a hard {@link EnsureUniqueIdentity}
10	 * conflict). Sets {@code possibleDuplicate} true and {@code possibleDuplicateOf} to that owner's id,
11	 * otherwise {@code possibleDuplicate} false. A declared household member ({@code sharesHousehold: true})
12	 * is never flagged. Runs before Save, so the flags persist and are read back on GET, and it sees only
13	 * the owners that existed before this create.
14	 */
15	public class FlagPossibleDuplicate {
16	
17	    public void service(@Val Owner owner, @Val Boolean sharesHousehold, OwnerRepository ownerRepository) {
18	        if (!Boolean.TRUE.equals(sharesHousehold)) {
19	            for (Owner existing : ownerRepository.findAll()) {
20	                if (softMatches(owner, existing)) {
21	                    owner.setPossibleDuplicate(true);
22	                    owner.setPossibleDuplicateOf(existing.getId());
23	                    return;
24	                }
25	            }
26	        }
27	        owner.setPossibleDuplicate(false);
28	    }
29	
30	    private static boolean softMatches(Owner owner, Owner existing) {
31	        return owner.getHouseholdId().equals(existing.getHouseholdId())
32	                && !owner.getTelephone().equals(existing.getTelephone());
33	    }
34	}
